data |> 
  ungroup() |> #remove by-participant grouping
  aggregate_Date(unit = "15 mins") |> #condense data to 1 day of 15-minute intervals
  gg_doubleplot(fill = melidos_colors[[site]]) |> #create double plot
  gg_photoperiod(melidos_coordinates[[site]]) #add photoperiod information
```

